function parkReaction(id,zone){const responses={plant:{bench:'Pip turns the plant toward the sunlight and checks a new leaf. “A window seat. Better benefits than the office.”',bea:'Bea: “Finally, a colleague who’s good at listening.”',ground:'Pip: “Some sun, some space. That makes two of us.”'},mug:{bench:'Bea: “Tea? I think this mug is finally earning its slogan.”',bea:'Bea: “People first. Tea immediately after.”',ground:'Pip: “A bold choice for a mug. We’ll watch our feet.”'},sketchbook:{bench:'Bea: “Leave it there. Ideas can have an afternoon off too.”',bea:'Bea opens a fresh page. “Want to help me draw somewhere better?”',ground:'Bea: “Very avant-garde. Let’s keep the pages out of the grass.”'},photo:{bench:'Pip props the photo against the bench. Five faces, three missed timers. “Still my favorite team portrait.”',bea:'Bea points out the blurred fork in the photo. “We were still laughing when the timer finally worked.”',ground:'Pip: “Still the same people, from a different angle.”'},award:{bench:'Bea slips a napkin beneath the award. “Excellent. A paperweight with transferable skills.”',bea:'Bea: “Thank you. I hereby award you one completely unproductive afternoon.”',ground:'Pip: “There. Finally, a grounded performance review.”'},poster:{bench:'Pip unrolls the signatures across the bench. Jo’s potato emerges first. “An uncanny likeness,” Pip says.',bea:'Bea: “I signed it before I learned how tiny the text would be.”',ground:'Pip smooths a corner. “Still worth making room for.”'},sticker:{bench:'Pip: “A tiny honk for everyone who made it outside.”',bea:'Bea: “I’m putting this on my next sketchbook.”',ground:'Pip: “Graham would like this placement documented.”'}};const line=responses[id]?.[zone]||'Something worth keeping.';if(!state.flags.invited&&line.includes('Bea'))return 'Pip: '+({plant:'“A quiet colleague for a quiet afternoon.”',mug:'“Tea for one. Still people first.”',sketchbook:'“I’ll get this back to Bea. The lunch drawing is safe.”',photo:'“I remember every one of those faces.”',award:'“It can hold down a page. That seems useful.”',poster:'“Jo’s potato. I’m keeping that.”',sticker:'“A small honk. Just for me.”'}[id]||'“Something worth keeping.”');return line;}
function selectParkItem(id){if(!state.ended||!endingKeys().includes(id))return;parkArranging=true;if(parkSelection.has(id))parkSelection.delete(id);else parkSelection.add(id);renderEnding();Array.from($('#keepsakes').children).find(b=>b.dataset.parkItem===id)?.focus({preventScroll:true});}
