if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'read_game_progress',description:'Read the current Out of Office progress, inventory, and next objective.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({room:state.room,objective:G.goal(state),packed:Object.keys(state.packed),flags:state.flags,ended:state.ended})},{name:'navigate_office_area',description:'Move to an office area in the active game.',inputSchema:{type:'object',properties:{room:{type:'string',enum:['desk','supply','lobby']}},required:['room'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||!spots[input.room]||!state.started||state.ended||!state.flags.tutorial)throw new Error('An active game and a valid room are required.');await room(input.room);return {room:state.room};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
